import React, { useState, useEffect } from 'react';
import API from '../utils/api';
import toast from 'react-hot-toast';

const Settings = () => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [updating, setUpdating] = useState(false);
  
  // Email form
  const [emailForm, setEmailForm] = useState({
    currentEmail: '',
    newEmail: '',
    confirmEmail: ''
  });
  
  // Password form
  const [passwordForm, setPasswordForm] = useState({
    currentPassword: '',
    newPassword: '',
    confirmPassword: ''
  });

  // Success messages
  const [emailSuccess, setEmailSuccess] = useState('');
  const [passwordSuccess, setPasswordSuccess] = useState('');

  useEffect(() => {
    loadUser();
  }, []);

  const loadUser = async () => {
    try {
      setLoading(true);
      const res = await API.get('/auth/me');
      setUser(res.data.user);
      setEmailForm({
        ...emailForm,
        currentEmail: res.data.user.email || ''
      });
    } catch (error) {
      toast.error('Failed to load user data');
      console.error('Error:', error);
    } finally {
      setLoading(false);
    }
  };

  // ===== UPDATE EMAIL =====
  const handleEmailSubmit = async (e) => {
    e.preventDefault();
    setEmailSuccess('');
    
    if (!emailForm.newEmail || !emailForm.confirmEmail) {
      toast.error('Please fill in all email fields');
      return;
    }

    if (emailForm.newEmail !== emailForm.confirmEmail) {
      toast.error('New emails do not match');
      return;
    }

    if (emailForm.newEmail === emailForm.currentEmail) {
      toast.error('New email is the same as current email');
      return;
    }

    if (!emailForm.newEmail.includes('@') || !emailForm.newEmail.includes('.')) {
      toast.error('Please enter a valid email address');
      return;
    }

    setUpdating(true);
    try {
      const res = await API.put('/auth/update', {
        email: emailForm.newEmail
      });
      
      if (res.data.success) {
        toast.success('Email updated successfully!');
        setEmailSuccess('✅ Email updated to: ' + emailForm.newEmail);
        setEmailForm({
          ...emailForm,
          currentEmail: emailForm.newEmail,
          newEmail: '',
          confirmEmail: ''
        });
        // Reload user data
        loadUser();
      }
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to update email');
    } finally {
      setUpdating(false);
    }
  };

  // ===== CHANGE PASSWORD =====
  const handlePasswordSubmit = async (e) => {
    e.preventDefault();
    setPasswordSuccess('');
    
    if (!passwordForm.currentPassword || !passwordForm.newPassword || !passwordForm.confirmPassword) {
      toast.error('Please fill in all password fields');
      return;
    }

    if (passwordForm.newPassword.length < 6) {
      toast.error('New password must be at least 6 characters');
      return;
    }

    if (passwordForm.newPassword !== passwordForm.confirmPassword) {
      toast.error('New passwords do not match');
      return;
    }

    if (passwordForm.newPassword === passwordForm.currentPassword) {
      toast.error('New password is the same as current password');
      return;
    }

    setUpdating(true);
    try {
      const res = await API.put('/auth/change-password', {
        currentPassword: passwordForm.currentPassword,
        newPassword: passwordForm.newPassword
      });
      
      if (res.data.success) {
        toast.success('Password changed successfully!');
        setPasswordSuccess('✅ Password changed successfully!');
        setPasswordForm({
          currentPassword: '',
          newPassword: '',
          confirmPassword: ''
        });
      }
    } catch (error) {
      toast.error(error.response?.data?.message || 'Failed to change password');
    } finally {
      setUpdating(false);
    }
  };

  if (loading) {
    return <div className="loading">Loading settings...</div>;
  }

  return (
    <div className="settings-page">
      <h2 className="page-title">⚙️ Settings</h2>
      
      <div className="settings-grid">
        {/* ===== CHANGE EMAIL ===== */}
        <div className="settings-card">
          <div className="settings-card-header">
            <span className="settings-icon">✉️</span>
            <div>
              <h3>Change Email</h3>
              <p>Update your account email address</p>
            </div>
          </div>
          
          {emailSuccess && (
            <div className="success-message">{emailSuccess}</div>
          )}
          
          <form onSubmit={handleEmailSubmit}>
            <div className="form-group">
              <label>Current Email</label>
              <input 
                type="email" 
                value={emailForm.currentEmail} 
                disabled 
                className="disabled-input"
              />
            </div>
            <div className="form-group">
              <label>New Email</label>
              <input 
                type="email" 
                value={emailForm.newEmail} 
                onChange={(e) => setEmailForm({ ...emailForm, newEmail: e.target.value })}
                placeholder="Enter new email address"
                required
              />
            </div>
            <div className="form-group">
              <label>Confirm New Email</label>
              <input 
                type="email" 
                value={emailForm.confirmEmail} 
                onChange={(e) => setEmailForm({ ...emailForm, confirmEmail: e.target.value })}
                placeholder="Confirm new email address"
                required
              />
            </div>
            <button type="submit" className="btn btn-primary" disabled={updating}>
              {updating ? 'Updating...' : '✉️ Update Email'}
            </button>
          </form>
        </div>

        {/* ===== CHANGE PASSWORD ===== */}
        <div className="settings-card">
          <div className="settings-card-header">
            <span className="settings-icon">🔒</span>
            <div>
              <h3>Change Password</h3>
              <p>Update your account password</p>
            </div>
          </div>
          
          {passwordSuccess && (
            <div className="success-message">{passwordSuccess}</div>
          )}
          
          <form onSubmit={handlePasswordSubmit}>
            <div className="form-group">
              <label>Current Password</label>
              <input 
                type="password" 
                value={passwordForm.currentPassword} 
                onChange={(e) => setPasswordForm({ ...passwordForm, currentPassword: e.target.value })}
                placeholder="Enter current password"
                required
              />
            </div>
            <div className="form-group">
              <label>New Password</label>
              <input 
                type="password" 
                value={passwordForm.newPassword} 
                onChange={(e) => setPasswordForm({ ...passwordForm, newPassword: e.target.value })}
                placeholder="Enter new password (min 6 characters)"
                required
              />
            </div>
            <div className="form-group">
              <label>Confirm New Password</label>
              <input 
                type="password" 
                value={passwordForm.confirmPassword} 
                onChange={(e) => setPasswordForm({ ...passwordForm, confirmPassword: e.target.value })}
                placeholder="Confirm new password"
                required
              />
            </div>
            <button type="submit" className="btn btn-primary" disabled={updating}>
              {updating ? 'Updating...' : '🔒 Change Password'}
            </button>
          </form>
        </div>

        {/* ===== ACCOUNT INFO ===== */}
        <div className="settings-card full-width">
          <div className="settings-card-header">
            <span className="settings-icon">👤</span>
            <div>
              <h3>Account Information</h3>
              <p>Your account details</p>
            </div>
          </div>
          
          <div className="account-info-grid">
            <div className="account-info-item">
              <span className="account-label">Username</span>
              <span className="account-value">{user?.username}</span>
            </div>
            <div className="account-info-item">
              <span className="account-label">Email</span>
              <span className="account-value">{user?.email}</span>
            </div>
            <div className="account-info-item">
              <span className="account-label">Full Name</span>
              <span className="account-value">{user?.fullName || 'Not set'}</span>
            </div>
            <div className="account-info-item">
              <span className="account-label">Role</span>
              <span className="account-value" style={{ textTransform: 'capitalize' }}>{user?.role}</span>
            </div>
            <div className="account-info-item">
              <span className="account-label">Account Status</span>
              <span className="account-value" style={{ color: '#28a745' }}>✅ Active</span>
            </div>
            <div className="account-info-item">
              <span className="account-label">Last Login</span>
              <span className="account-value">{user?.lastLogin ? new Date(user.lastLogin).toLocaleString() : 'N/A'}</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Settings;
